//! `r3akt-sigil radios`: view and manage the radio identity database.

use std::path::{Path, PathBuf};

use anyhow::{Context, Result, ensure};
use clap::Subcommand;
use zeroize::Zeroizing;

use crate::config::Config;
use crate::identity::{PASSPHRASE_ENV, RadioRecord, Registry, Source, parse_identity_file};

#[derive(Subcommand)]
pub enum Action {
    /// List registered radios and the Reticulum identities that sign for them.
    List,
    /// Register a radio with a new identity generated by Sigil.
    Add {
        /// BSS radio ID as the radio sends it, e.g. Corvo.
        id: String,
        /// Display name announced for the radio. Defaults to the ID.
        #[arg(long)]
        name: Option<String>,
    },
    /// Assign an existing Reticulum identity to a radio, e.g. the operator's
    /// Sideband or REM identity, so RCH attributes messages to that address.
    Import {
        /// BSS radio ID as the radio sends it.
        id: String,
        /// Reticulum identity file: 64 raw bytes, or the same as hex text.
        #[arg(long)]
        identity_file: PathBuf,
        /// Display name announced for the radio.
        #[arg(long)]
        name: Option<String>,
        /// Replace the radio's current identity. Its LXMF address changes.
        #[arg(long)]
        replace: bool,
    },
    /// Delete a radio and its private key. Cannot be undone without a backup.
    Remove {
        /// BSS radio ID.
        id: String,
        /// Confirm the deletion.
        #[arg(long)]
        yes: bool,
    },
}

fn print(radios: &[RadioRecord]) {
    println!(
        "{:<12} {:<20} {:<32} {:<9} {:<11} {:<17} LAST POSITION",
        "BSS ID", "NAME", "LXMF ADDRESS", "IDENTITY", "ALLOWLISTED", "LAST SEEN (UTC)"
    );
    for radio in radios {
        let source = match radio.source {
            Source::Generated => "generated",
            Source::Imported => "imported",
        };
        let seen = radio.last_seen.map_or_else(
            || "never".to_owned(),
            |t| t.format("%Y-%m-%d %H:%M").to_string(),
        );
        let position = radio.last_position.map_or_else(
            || "none".to_owned(),
            |last| {
                format!(
                    "{:.5}, {:.5} at {}",
                    last.position.latitude,
                    last.position.longitude,
                    last.received_at.format("%Y-%m-%d %H:%M")
                )
            },
        );
        println!(
            "{:<12} {:<20} {:<32} {:<9} {:<11} {:<17} {position}",
            radio.bss_id,
            radio.display_name,
            radio.lxmf_destination,
            source,
            if radio.allowlisted { "yes" } else { "no" },
            seen,
        );
    }
}

fn note_allowlist(radio: &RadioRecord) {
    if !radio.allowlisted {
        println!(
            "Note: {} is not in [identity].allowlist, so its messages are not published.",
            radio.bss_id
        );
    }
}

pub fn run(config_path: &Path, action: Action) -> Result<()> {
    let config = Config::load(config_path)?;
    let passphrase = Zeroizing::new(
        std::env::var(PASSPHRASE_ENV).with_context(|| format!("set {PASSPHRASE_ENV} first"))?,
    );
    let registry = Registry::open(&config.identity, &passphrase)?;
    match action {
        Action::List => {
            println!(
                "Radio identity database {}",
                registry.database_path().display()
            );
            print(&registry.list()?);
            match registry.unidentified_address()? {
                Some(address) => println!(
                    "Speech without a BSS ID is published as {address} when unidentified_sender is on."
                ),
                None => println!("No unidentified-speech identity has been created yet."),
            }
        }
        Action::Add { id, name } => {
            let radio = registry.add(&id, name.as_deref())?;
            print(std::slice::from_ref(&radio));
            note_allowlist(&radio);
        }
        Action::Import {
            id,
            identity_file,
            name,
            replace,
        } => {
            let bytes = Zeroizing::new(
                std::fs::read(&identity_file)
                    .with_context(|| format!("read identity file {}", identity_file.display()))?,
            );
            let identity = parse_identity_file(&bytes)?;
            let radio = registry.import(&id, name.as_deref(), &identity, replace)?;
            print(std::slice::from_ref(&radio));
            note_allowlist(&radio);
            println!(
                "Messages from {} are now signed by {}. Restart a running gateway to use it.",
                radio.bss_id, radio.lxmf_destination
            );
        }
        Action::Remove { id, yes } => {
            ensure!(
                yes,
                "removing {id} deletes its private key; pass --yes to confirm (back up {} first)",
                registry.database_path().display()
            );
            if registry.remove(&id)? {
                println!("Removed {id} and its private key.");
            } else {
                println!("{id} was not registered.");
            }
        }
    }
    Ok(())
}
